-- Catalogo de productos del laboratorio (tabla ProductosLab).
-- Lista provista por el laboratorio: acrilicos, encerados, implantologia,
-- impresion en resina LCD, libre de metal, metal, uclas/anillos en cromo y yesos.
CREATE TABLE IF NOT EXISTS public."ProductosLab" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  codigo text NOT NULL UNIQUE,
  nombre text NOT NULL,
  codigo_categoria text,
  categoria text,
  iva numeric(5,2) DEFAULT 0,
  activo boolean DEFAULT true,
  fases_fabricacion text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Por si la tabla ya existía sin la columna.
ALTER TABLE public."ProductosLab" ADD COLUMN IF NOT EXISTS fases_fabricacion text;

ALTER TABLE public."ProductosLab" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "ProductosLab: CRUD a usuarios autenticados" ON public."ProductosLab"
  FOR ALL TO authenticated USING (true) WITH CHECK (true);

